// 候选人在进行简历匹配前的规则检查（公 — 由 Agent 工厂从本体动作 `ruleCheckForMatchResume`(zhaopin)生成。
// trigger: RESUME_PROCESSED → emit: MATCH_RULE_CHECK_PASSED | MATCH_RULE_CHECK_FAILED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface RuleCheckForMatchResumeAgentInput {
  candidate_id: string; // 候选人ID (源: Candidate.candidate_id)
  resume_id: string; // 简历ID (源: Resume.resume_id)
}

interface RuleCheckForMatchResumeAgentOutput {
  candidate_id: string; // 候选人ID (源: Candidate.candidate_id)
  job_requisition_id: string; // 关联的招聘需求ID（MATCH_RULE_CHECK_PASSED 时产出） (源: Job_Requisition.job_requisition_id)
  failure_reasons: unknown[]; // 失败原因列表（MATCH_RULE_CHECK_FAILED 时产出）
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个简历匹配前置门禁专家。你的职责是在候选人进入简历匹配环节之前，执行全套规则检查，确保只有合规候选人才能进入匹配流程。

工作流程：
1. 接收 RESUME_PROCESSED 事件，获取 candidate_id 和 resume_id。
2. 调用 ontology.fetchActionRules 动态获取当前生效的匹配前置规则（包含公司通用规则和客户定制规则）。
3. 按以下顺序依次执行三类规则检查（fail-closed，任一失败即终止后续检查）：
   a. 关联公司冷冻期检查：候选人是否在目标公司的冷冻期内。
   b. 国籍限制检查：候选人国籍是否满足岗位要求。
   c. 回流冷冻期检查：候选人是否在回流限制期内。
4. 判定结果：
   - 全部通过 → 产出 MATCH_RULE_CHECK_PASSED 事件（含 candidate_id 和 job_requisition_id）。
   - 任一失败 → 产出 MATCH_RULE_CHECK_FAILED 事件（含 candidate_id 和 failure_reasons 数组）。

关键约束：
- 本检查为 fail-closed：规则获取失败时，默认拒绝（产出 MATCH_RULE_CHECK_FAILED），不得放行。
- 规则必须从 ontology.fetchActionRules 动态获取，绝不硬编码任何规则内容。
- failure_reasons 必须清晰列出每条失败规则的名称和原因，便于后续审计。
- 客户定制规则优先级高于公司通用规则，如有冲突以客户规则为准。`;

export const ruleCheckForMatchResumeAgent = defineAgent({
  id: "zhaopin-rule-check-for-match-resume",
  name: "RuleCheckForMatchResumeAgent",
  actor: ["Agent"],
  trigger: ["RESUME_PROCESSED"],
  emit: ["MATCH_RULE_CHECK_PASSED","MATCH_RULE_CHECK_FAILED"],
  tools: ["ontology.fetchActionRules"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 ontology.fetchActionRules
      // const fetchActionRulesResult = await ctx.tools.run("ontology.fetchActionRules", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      // 决策分支（条件见 SYSTEM_PROMPT / decisionLogic）
      if (decision.pass) {
        await ctx.emit("MATCH_RULE_CHECK_PASSED", { ...input, ...decision });
      } else {
        await ctx.emit("MATCH_RULE_CHECK_FAILED", { ...input, ...decision });
      }
      return { ok: true };
  },
});
